public void rotate(int[] nums, int k) {
    int n = nums.length;
    k %= n;
    int[] out = new int[n];
    for (int i = 0; i < n; i++) {
        out[(i + k) % n] = nums[i];
    }
    System.arraycopy(out, 0, nums, 0, n);
}

public void rotate(int[] nums, int k) {
    int n = nums.length;
    k %= n;
    reverse(nums, 0, n - 1);
    reverse(nums, 0, k - 1);
    reverse(nums, k, n - 1);
}

private void reverse(int[] nums, int lo, int hi) {
    while (lo < hi) {
        int tmp = nums[lo];
        nums[lo] = nums[hi];
        nums[hi] = tmp;
        lo++;
        hi--;
    }
}

